/* Remote project lifecycle acceptance against an isolated FakeHost backend.
 * node tests/check_remote_projects.cjs DEBUG_URL APP_URL_WITH_TOKEN OUTPUT_DIR --fake-host
 * Never point this deployment check at a production/Docker backend. It creates
 * and removes only projects with the unique name generated by this invocation.
 */
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { openSavedLab, experimentAction } = require('./browser_projects.cjs');

const [debugURL, appURL, output, fixtureFlag] = process.argv.slice(2);
if (!debugURL || !appURL || !output || fixtureFlag !== '--fake-host')
  throw Error('Expected DEBUG_URL APP_URL_WITH_TOKEN OUTPUT_DIR --fake-host (isolated fixture only)');

(async () => {
  const app = new URL(appURL);
  const token = new URLSearchParams(app.hash.slice(1)).get('token');
  assert.ok(token, 'A test backend token is required');
  const suffix = Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 7);
  const projectName = '远程项目验收 ' + suffix;
  const failedName = '创建失败验收 ' + suffix;
  const ownedNames = new Set([projectName, failedName]);
  const checks = [], requests = [], failures = [], exceptions = [];
  let id, acceptDialog = true, dialogCount = 0, seq = 0;
  const pending = new Map();
  fs.mkdirSync(output, { recursive: true });
  const target = await (await fetch(debugURL + '/json/new?about:blank', { method: 'PUT' })).json();
  const socket = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    socket.addEventListener('open', resolve, { once: true });
    socket.addEventListener('error', reject, { once: true });
  });
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const requestId = ++seq;
    const timer = setTimeout(() => {
      pending.delete(requestId);
      reject(Error('CDP timeout: ' + method));
    }, 20000);
    pending.set(requestId, { resolve, reject, timer });
    socket.send(JSON.stringify({ id: requestId, method, params }));
  });
  socket.addEventListener('message', ({ data }) => {
    const message = JSON.parse(data), job = pending.get(message.id);
    if (job) {
      clearTimeout(job.timer);
      pending.delete(message.id);
      message.error ? job.reject(Error(JSON.stringify(message.error))) : job.resolve(message.result);
    }
    if (message.method === 'Runtime.exceptionThrown')
      exceptions.push(message.params.exceptionDetails.exception?.description || message.params.exceptionDetails.text);
    if (message.method === 'Page.javascriptDialogOpening') {
      dialogCount++;
      const accept = acceptDialog;
      acceptDialog = true;
      void send('Page.handleJavaScriptDialog', { accept }).catch(error => exceptions.push(error.message));
    }
    if (message.method === 'Network.requestWillBeSent') {
      const request = message.params.request;
      const url = new URL(request.url);
      if (url.pathname.startsWith('/api/'))
        requests.push({ origin: url.origin, pathname: url.pathname, method: request.method });
    }
    if (message.method === 'Network.loadingFailed' && message.params.corsErrorStatus)
      failures.push(message.params.corsErrorStatus);
  });
  const evaluate = async expression => {
    const result = await send('Runtime.evaluate', {
      expression, returnByValue: true, awaitPromise: true, userGesture: true,
    });
    if (result.exceptionDetails)
      throw Error(result.exceptionDetails.exception?.description || result.exceptionDetails.text);
    return result.result.value;
  };
  const wait = async expression => {
    for (let attempt = 0; attempt < 150; attempt++) {
      if (await evaluate(expression)) return;
      await new Promise(resolve => setTimeout(resolve, 100));
    }
    const state = await evaluate('({toast:document.querySelector("#toast")?.textContent,name:document.querySelector("#lab-name")?.textContent,save:document.querySelector("#save-state")?.textContent,phase:document.querySelector("#phase")?.textContent,error:document.querySelector("#project-name-error")?.textContent})');
    throw Error('Condition not met: ' + expression + '; state=' + JSON.stringify(state));
  };
  const click = async selector => {
    const location = await evaluate(`(() => {
      const el = document.querySelector(${JSON.stringify(selector)});
      if (!el) throw Error('Missing element: ' + ${JSON.stringify(selector)});
      if (el.disabled) throw Error('Disabled element: ' + ${JSON.stringify(selector)});
      el.scrollIntoView({block:'nearest',inline:'nearest'});
      const r = el.getBoundingClientRect();
      return {x:r.left+r.width/2,y:r.top+r.height/2};
    })()`);
    for (const type of ['mousePressed', 'mouseReleased'])
      await send('Input.dispatchMouseEvent', { type, ...location, button: 'left', clickCount: 1 });
  };
  const input = (selector, value) => evaluate(`(() => {
    const el = document.querySelector(${JSON.stringify(selector)});
    if (!el) throw Error('Missing input: ' + ${JSON.stringify(selector)});
    el.value = ${JSON.stringify(value)};
    el.dispatchEvent(new Event('input', {bubbles:true}));
  })()`);
  const action = selector => experimentAction(evaluate, wait, click, selector);
  const api = async (pathname, method = 'GET', body, extraHeaders = {}) => {
    const response = await fetch(app.origin + pathname, {
      method,
      headers: { Authorization: 'Bearer ' + token, ...(body === undefined ? {} : { 'Content-Type': 'application/json' }), ...extraHeaders },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
    return { status: response.status, value: await response.json() };
  };
  const read = async () => {
    const result = await api('/api/labs/' + id);
    assert.equal(result.status, 200, 'Read the remote project');
    return result.value;
  };
  const assertRequest = (method, pathname) => {
    assert.ok(requests.some(request => request.method === method && request.pathname === pathname),
      'Browser must send ' + method + ' ' + pathname + ' to the current server');
  };
  const shot = async filename => {
    const screenshot = await send('Page.captureScreenshot');
    fs.writeFileSync(path.join(output, filename), Buffer.from(screenshot.data, 'base64'));
  };
  // Fail only one matching browser request; all unrelated polling stays real.
  const failNext = (pathname, methods, marker) => evaluate(`(() => {
    const realFetch = window.fetch;
    window.fetch = function(resource, options = {}) {
      const requestURL = new URL(typeof resource === 'string' || resource instanceof URL ? resource : resource.url, location.href);
      const method = (options.method || resource.method || 'GET').toUpperCase();
      if (requestURL.pathname === ${JSON.stringify(pathname)} && ${JSON.stringify(methods)}.includes(method)) {
        window.fetch = realFetch;
        return Promise.resolve(new Response(JSON.stringify({error:${JSON.stringify(marker)}}), {
          status:503, headers:{'Content-Type':'application/json'}
        }));
      }
      return realFetch.call(this, resource, options);
    };
  })()`);
  const addHost = async count => {
    await click('[data-category="host"]');
    await click('.device-card.host');
    await wait(`document.querySelectorAll('.topology-node').length === ${count}`);
  };
  const saved = () => wait('document.querySelector("#save-state")?.textContent === "已保存"');
  const blank = () => wait('document.querySelector("#lab-name")?.textContent.includes("空白画布") && document.querySelectorAll(".topology-node").length === 0');
  let success = false;
  try {
    await send('Page.enable');
    await send('Runtime.enable');
    await send('Network.enable');
    await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false });
    await send('Page.navigate', { url: appURL });
    await wait('!!document.querySelector("#empty-new-lab") && !document.querySelector("#access-dialog")?.open');
    assert.equal(await evaluate('document.querySelector("#server-host")?.textContent.trim()'), app.host,
      'The displayed server is the server connected by this Web page');
    const environment = await api('/api/environment');
    assert.equal(environment.status, 200);
    assert.equal(environment.value.ready, true, 'Use the deployment-capable isolated FakeHost fixture');
    const beforeList = (await api('/api/labs')).value;

    await click('#menu-experiment');
    for (const [selector, label] of [['#new-lab', '新建项目'], ['#open-lab', '打开项目'], ['#menu-save', '保存项目'], ['#close-lab', '关闭项目']])
      assert.ok(await evaluate(`document.querySelector(${JSON.stringify(selector)})?.textContent.includes(${JSON.stringify(label)})`), label);
    await wait('!document.querySelector("#new-lab").disabled');
    await click('#new-lab');
    await wait('document.querySelector("#project-name-dialog")?.open');
    await click('.project-name-cancel');
    assert.deepEqual((await api('/api/labs')).value, beforeList, 'Cancel does not create a remote record');
    await action('#new-lab');
    await input('#project-name-input', '   ');
    await click('#confirm-project-name');
    await wait('!!document.querySelector("#project-name-error")');
    assert.deepEqual((await api('/api/labs')).value, beforeList, 'Invalid names do not create a remote record');
    await input('#project-name-input', '  ' + projectName + '  ');
    await click('#confirm-project-name');
    await wait('!document.querySelector("#project-name-dialog").open');
    await saved();
    const created = (await api('/api/labs')).value.filter(project => project.name === projectName);
    assert.equal(created.length, 1, 'Create persists immediately without clicking Save');
    id = created[0].id;
    assert.equal((await read()).topology.nodes.length, 0);
    assertRequest('POST', '/api/labs');
    checks.push('create immediately persists on current server; cancellation and invalid names are safe');

    await addHost(1);
    const firstNode = await evaluate('document.querySelector(".topology-node").dataset.node');
    // Save can report failure without replacing the existing server copy.
    await failNext('/api/labs/' + id + '/save', ['POST'], 'remote-save-failed-' + suffix);
    await click('#save');
    await wait(`document.querySelector('#toast')?.textContent.includes(${JSON.stringify('remote-save-failed-' + suffix)})`);
    assert.equal((await read()).topology.nodes.length, 0);
    assert.equal(await evaluate('document.querySelectorAll(".topology-node").length'), 1);
    assert.ok(await evaluate('document.querySelector("#save-state").textContent.includes("未保存")'));
    await click('#save');
    await saved();
    assert.equal((await read()).topology.nodes.length, 1);
    checks.push('failed save retains browser edits and remote version; retry persists topology');

    // New-project failure must preserve even uncommitted inspector properties.
    await click(`.topology-node[data-node="${firstNode}"] .node-name`);
    await input('#node-name', 'pc-kept-draft');
    await failNext('/api/labs', ['POST'], 'remote-create-failed-' + suffix);
    await action('#new-lab');
    await input('#project-name-input', failedName);
    await click('#confirm-project-name');
    await wait(`document.querySelector('#project-name-error')?.textContent.includes(${JSON.stringify('remote-create-failed-' + suffix)})`);
    assert.ok(await evaluate(`document.querySelector('#lab-name').textContent.includes(${JSON.stringify(projectName)})`));
    assert.equal(await evaluate('document.querySelector("#node-name").value'), 'pc-kept-draft');
    assert.equal((await api('/api/labs')).value.some(project => project.name === failedName), false);
    await click('.project-name-cancel');
    await click('#save');
    await saved();
    assert.equal((await read()).topology.nodes[0].name, 'pc-kept-draft');
    checks.push('failed new project preserves the existing project and inspector draft');

    await addHost(2);
    const beforeCancel = dialogCount;
    acceptDialog = false;
    await action('#close-lab');
    assert.equal(dialogCount, beforeCancel + 1);
    assert.equal(await evaluate('document.querySelectorAll(".topology-node").length'), 2);
    await failNext('/api/labs/' + id + '/close', ['POST'], 'remote-close-failed-' + suffix);
    await action('#close-lab');
    await wait(`document.querySelector('#toast')?.textContent.includes(${JSON.stringify('remote-close-failed-' + suffix)})`);
    assert.equal(await evaluate('document.querySelectorAll(".topology-node").length'), 2);
    assert.equal((await read()).topology.nodes.length, 1);
    await action('#close-lab');
    await blank();
    assert.equal((await read()).topology.nodes.length, 1, 'Close retains the saved remote project');
    assertRequest('POST', '/api/labs/' + id + '/close');
    checks.push('close cancellation/failure preserves draft; successful close retains remote project');

    await failNext('/api/labs/' + id + '/open', ['POST'], 'remote-open-failed-' + suffix);
    await action('#open-lab');
    await wait(`!!document.querySelector('.open-lab-item[data-lab-id="${id}"]')`);
    await click(`.open-lab-item[data-lab-id="${id}"]`);
    await click('#confirm-open-lab');
    await wait(`document.body.textContent.includes(${JSON.stringify('remote-open-failed-' + suffix)})`);
    assert.ok(await evaluate('document.querySelector("#lab-name").textContent.includes("空白画布")'));
    assert.equal(await evaluate('document.querySelectorAll(".topology-node").length'), 0);
    await click('#confirm-open-lab');
    await wait('!document.querySelector("#open-lab-dialog").open && document.querySelectorAll(".topology-node").length === 1');
    assertRequest('POST', '/api/labs/' + id + '/open');
    await saved();
    await shot('remote-project-open.png');
    checks.push('failed open preserves current canvas; retry opens saved remote topology');

    await wait('!!document.querySelector("#deploy") && !document.querySelector("#deploy").disabled');
    await click('#deploy');
    await wait('document.querySelector("#phase")?.classList.contains("running")');
    const deployed = await read();
    assert.ok(deployed.runtime.deployment);
    assert.equal(deployed.runtime.phase, 'running');
    assert.equal(Object.keys(deployed.runtime.nodes).length, 1);
    assertRequest('POST', '/api/labs/' + id + '/deploy');
    await click('#save');
    await wait('document.querySelector("#save-state")?.textContent === "部分设备仅保存拓扑"');
    assert.ok(await evaluate('document.querySelector("#toast")?.textContent.includes("不支持运行配置保存")'));
    assert.equal((await read()).runtime.deployment, deployed.runtime.deployment);
    checks.push('project save reports unsupported PC running configuration without claiming full save');
    await shot('remote-project-deployed.png');
    await action('#close-lab');
    await blank();
    const closed = await read();
    assert.equal(closed.runtime.deployment, deployed.runtime.deployment);
    assert.equal(closed.runtime.phase, 'running');
    assert.deepEqual(closed.runtime.nodes, deployed.runtime.nodes, 'Close must retain deployed devices');
    await openSavedLab(evaluate, wait, click, id);
    await wait('document.querySelector("#phase")?.classList.contains("running")');
    await send('Page.reload');
    await wait('!!document.querySelector("#menu-experiment") && !document.querySelector("#access-dialog")?.open');
    await blank();
    await openSavedLab(evaluate, wait, click, id);
    await wait('document.querySelector("#phase")?.classList.contains("running")');
    assert.equal((await read()).runtime.deployment, deployed.runtime.deployment);
    checks.push('deployment runs on current server; close/reopen/reload preserve remote devices');

    const foreign = { Origin: 'https://foreign.invalid' };
    for (const [pathname, body] of [['/api/labs', { name: failedName }], ['/api/labs/' + id + '/open', {}], ['/api/labs/' + id + '/close', {}], ['/api/labs/' + id + '/deploy', {}]]) {
      const denied = await api(pathname, 'POST', body, foreign);
      assert.equal(denied.status, 403, 'Reject foreign Origin: ' + pathname);
    }
    assert.equal((await read()).runtime.deployment, deployed.runtime.deployment);
    assert.ok(requests.length > 0);
    assert.deepEqual([...new Set(requests.map(request => request.origin))], [app.origin], 'All browser API requests use the connected Web origin');
    assert.deepEqual(failures, [], 'No CORS errors during same-origin project operations');
    assert.deepEqual(exceptions, [], 'No unhandled browser errors');
    checks.push('foreign Origin remains rejected; all browser APIs use current Web origin');
    success = true;
  } finally {
    // Cleanup verifies ownership and never touches fixture/user projects.
    try {
      const projects = await api('/api/labs');
      assert.equal(projects.status, 200, 'List test projects for cleanup');
      for (const project of projects.value.filter(project => ownedNames.has(project.name))) {
        const existing = await api('/api/labs/' + project.id);
        assert.equal(existing.status, 200);
        assert.ok(ownedNames.has(existing.value.topology.name));
        if (existing.value.runtime?.deployment) {
          const stopped = await api('/api/labs/' + project.id + '/destroy', 'POST', {});
          assert.equal(stopped.status, 202, 'Cleanup only this run\'s deployed project');
          let idle = false;
          for (let attempt = 0; attempt < 100; attempt++) {
            const current = await api('/api/labs/' + project.id);
            if (current.value.runtime?.phase === 'idle') { idle = true; break; }
            await new Promise(resolve => setTimeout(resolve, 100));
          }
          assert.ok(idle, 'Wait for test deployment cleanup');
        }
        assert.equal((await api('/api/labs/' + project.id, 'DELETE')).status, 200);
      }
    } catch (error) {
      success = false;
      throw error;
    } finally {
      await evaluate('window.onbeforeunload=null;window.addEventListener("beforeunload",event=>event.stopImmediatePropagation(),{capture:true})').catch(() => {});
      await send('Page.close').catch(() => {});
      socket.close();
      for (const job of pending.values()) clearTimeout(job.timer);
      fs.writeFileSync(path.join(output, 'remote-project-results.json'), JSON.stringify({ ok: success, checks, apiOrigin: app.origin, requests, corsErrors: failures, exceptions }, null, 2));
    }
  }
  console.log(JSON.stringify({ ok: success, checks, apiOrigin: app.origin, screenshots: output }, null, 2));
})().catch(error => { console.error(error); process.exitCode = 1; });
